	SHOWDOWNS_INFO_VAULT = "La settimanale dà un Riftstalker's Cache e conta per la riga World del tuo Great Vault.",
	SHOWDOWNS_INFO_HWT = "L'Heroic World Tier non richiede sblocco — scegli Normal o Heroic al portale.",
	TAB_PROF_ACADEMY = "Professions 101",
	INFO_DRAWER_BODY_PROFACADEMY = "Un corso per principianti sul sistema di professioni di Midnight: cosa sono i Knowledge Points, come scegliere gli alberi di specializzazione senza pentimenti, da dove vengono le ricette e la tua routine settimanale. Ogni capitolo ha un piccolo compito pratico — spuntalo man mano. Il progresso è salvato per personaggio.",
	PROFACAD_SUBTITLE = "Professioni per principianti — cos'è la Knowledge, come scegliere gli alberi in sicurezza e la tua routine settimanale. Le tue professioni sono rilevate sotto; ogni professione ha il suo capitolo iniziale, mostrato solo per le professioni che hai.",
	PROFACAD_PROGRESS_FMT = "Progresso: %d/%d capitoli",
	PROFACAD_TASK_AUTO_HINT = "(si spunta da solo quando rilevato)",
	PROFACAD_BTN_WORKORDER = "Waypoint: stazione Work Order (Flaresworn)",
	PROFACAD_WAYPOINT_WORKORDER = "Stazione Work Order — Silvermoon Bazaar",
	PROFACAD_PROFS_LINE_FMT = "Le tue professioni: %s",
	PROFACAD_PROFS_NONE = "Ancora nessuna professione su questo personaggio.",
	PROFACAD_ADVICE_PICK_FMT = "Slot libero? Buona scelta per la tua classe: %s + %s. %s",
	PROFACAD_ADVICE_ALT_FMT = "Alternativa solida per qualsiasi classe: %s + %s — flask e pozioni si vendono tutto l'anno.",
	PROFACAD_WHY_PLATE = "Indossi plate: crafta e potenzia la tua armatura, con Mining a fornirti i materiali.",
	PROFACAD_WHY_MAIL = "Indossi mail: il Leatherworking crafta armatura mail, e lo Skinning fornisce il cuoio.",
	PROFACAD_WHY_LEATHER = "Indossi leather: crafta il tuo equipaggiamento, e lo Skinning fornisce i materiali.",
	PROFACAD_WHY_CLOTH = "Indossi cloth: il Tailoring crafta il tuo equipaggiamento, e l'Enchanting trasforma i drop in eccesso in materiali.",
	PROFACAD_SPEC_LINE_FMT = "%s: %d KP spesi, %d disponibili — alberi iniziati: %s",
	PROFACAD_SPEC_NONE_STARTED = "ancora nessuno",
	PROF_ESSENCE_FMT = "Materiali da disenchant settimanali nelle borse: %s",
	PROF_GENERATE_TREASURES_BTN = "Genera Route Treasures",
	PROF_GENERATE_BOOKS_BTN = "Genera Route Books",
	PROFACAD_ADVISE_NEXT_FMT = "Consiglio: prossimi punti in %s (root %d/%d) — il capitolo sotto spiega perché.",
	PROFACAD_ADVISE_DONE = "Consiglio: root consigliati completi — spingi i sub-node o distribuisci negli alberi rimanenti.",
	PROFHUB_TAB_OVERVIEW = "Panoramica",
	PROFHUB_TAB_TREASURES = "Treasures & Books",
	PROFHUB_TAB_COURSE = "Corso (101)",
	PROFHUB_OVERVIEW_HINT = "Treasures & Books: tesori e libri KP una tantum con waypoint. Corso (101): il corso per principianti — i capitoli appaiono per le tue professioni. Checklist KP settimanale: in arrivo.",
	INFO_DRAWER_BODY_PROFHUB = "Tutto ciò che riguarda le professioni in un posto. La Panoramica mostra le tue professioni, i Knowledge Points e i consigli sull'albero in tempo reale; Treasures & Books traccia le raccolte KP una tantum con waypoint; Corso (101) è il corso per principianti.",
	PROFACAD_CH_KNOWLEDGE_TITLE = "Cos'è la Knowledge?",
	PROFACAD_CH_KNOWLEDGE_BODY = "Ogni professione di crafting e raccolta in Midnight ha un albero di specializzazione, e i Knowledge Points (KP) sono il modo in cui lo riempi. Guadagni KP da fonti una tantum (primi craft, tesori nascosti, libri renown) e da attività settimanali — è pensato per accumularsi nell'arco di settimane, non giorni.\n\nCooking, Fishing e Archaeology non hanno alberi e non richiedono KP.\n\nNon stressarti se sei \"indietro\": c'è un sistema di recupero, e questo corso ti accompagna in tutto un passo alla volta.",
	PROFACAD_CH_KNOWLEDGE_TASK = "Apri la finestra delle professioni (tasto predefinito: K) e dai un'occhiata alla tab Specializzazioni.",
	PROFACAD_CH_GEARUP_TITLE = "Equipaggiati: strumenti, stazioni e prime ricette",
	PROFACAD_CH_GEARUP_BODY = "Prima cosa importante: il menu a tendina in cima alla finestra delle professioni cambia i tier di espansione — tutto in questo corso riguarda il tier MIDNIGHT. Non lo vedi nella lista? Imparalo dagli addestratori di Silvermoon.\n\nOgni professione ha anche il suo equipaggiamento — 1 strumento e 2 accessori — in slot speciali in cima alla finestra delle professioni (K). Senza uno strumento equipaggiato, molte ricette semplicemente non si craftano. La maggior parte di strumenti e accessori sono craftati da ALTRE professioni (Blacksmithing, Leatherworking) — comprali all'Auction House sotto Profession Equipment, o chiedi a un crafter; il vendor di forniture a volte ha le basi. L'Enchanting fa eccezione e crafta le proprie bacchette: compra la bacchetta base economica dal vendor, crafta la versione Runed all'Enchanter's Lectern (ricetta da addestratore a skill 1), equipaggiala.\n\nPulsante di craft grigio? Leggi la riga dei requisiti nella ricetta: ti dice se ti manca uno strumento o se devi stare a una stazione (incudine, lectern, fuoco da cucina...). Le stazioni sono nel distretto degli addestratori a Silvermoon.\n\nPoi impara le prime ricette dall'addestratore e craftale — skill 25 sblocca i tuoi alberi di specializzazione, e ogni primo craft dà +1 KP.",
	PROFACAD_CH_GEARUP_TASK = "Equipaggia uno strumento per ognuna delle tue professioni.",
	PROFACAD_CH_TREES_TITLE = "Scegliere gli alberi — senza pentimenti",
	PROFACAD_CH_TREES_BODY = "I Knowledge Points si fissano nel momento in cui li spendi — con un'eccezione. Dalla patch 12.1 puoi annullare tutto |cffffffffuna volta per professione|r, da Theremis a Silvermoon. Una volta. Dopo è permanente, e attenzione: quel reset cancella anche le ricette imparate tramite i knowledge points.\n\nBuona notizia per i nervi: non puoi |cffffffffsprecare|r punti. Continua a raccoglierli e alla fine potrai riempire ogni ramo. L'unica cosa che puoi sbagliare è |cffffffffl'ordine|r.\n\nGli alberi si sbloccano col salire della skill (il primo intorno a skill 25, altri più avanti). Lo schema classico: scegli UN albero adatto al tuo obiettivo, riempi prima il suo nodo root (spesso ~30 punti), poi spingi un sotto-ramo (~20 punti) prima di toccare altri alberi.\n\nUna volta che hai delle professioni, i loro capitoli iniziali qui sotto danno una build di partenza concreta — e MH mostra consigli in tempo reale per i tuoi alberi proprio qui.",
	PROFACAD_CH_TREES_TASK = "Guarda i tuoi alberi e decidi UN primo obiettivo — non spendere ancora nulla.",
	PROFACAD_CH_RECIPES_TITLE = "Da dove vengono le ricette?",
	PROFACAD_CH_RECIPES_BODY = "Le ricette vengono da cinque posti: il tuo addestratore (comprale mentre sali di skill), i tuoi alberi di specializzazione (si sbloccano spendendo KP), i vendor Moxie (prossimo capitolo), le ricompense renown, e i drop dal mondo o i tesori.\n\nRegola pratica: crafta ogni nuova ricetta almeno una volta. Ogni primo craft dà +1 KP e 10x Moxie — anche se vendi il risultato.\n\nSe una guida menziona una ricetta che non hai, controlla da dove viene prima di farmarla.",
	PROFACAD_CH_RECIPES_TASK = "Impara una nuova ricetta e craftala una volta (primo craft = +1 KP + Moxie).",
	PROFACAD_CH_MOXIE_TITLE = "Moxie, i tuoi soldi per gli acquisti",
	PROFACAD_CH_MOXIE_BODY = "L'Artisan's Moxie è una valuta specifica per professione: il tuo Enchanting Moxie compra solo cose di Enchanting. Guadagni circa 5x Moxie per KP, e 10x dai primi craft.\n\nSpendilo dai vendor di professione a Silvermoon per nuove ricette, sacchi di materiali e libri che danno KP bonus.\n\nConsiglio: non accumulare all'infinito — le prime ricette e i libri KP sono il miglior affare.",
	PROFACAD_CH_MOXIE_TASK = "Trova il tuo Moxie nella tab delle valute e controlla il saldo.",
	PROFACAD_CH_WEEKLY_TITLE = "La tua routine settimanale",
	PROFACAD_CH_WEEKLY_BODY = "La maggior parte dei KP viene da fonti settimanali ripetibili. Le basi per ogni professione:\n\n1. Quest settimanale dell'addestratore — si sblocca dopo la quest introduttiva da Captain Flaresworn (stazione Work Order, Silvermoon Bazaar). L'Enchanting richiede prima skill 25.\n2. Due oggetti casuali da tesori-drop dai contenitori del mondo aperto (+2 KP ciascuno).\n3. Un Thalassian Treatise (+1 KP) — craftato dall'Inscription; warbound, quindi un alt o un work order te ne procura uno.\n4. Settimana del Darkmoon Faire: +3 KP e +15 Moxie, ogni mese.\n\nHai saltato una settimana? Il sistema di recupero restituisce lentamente i KP persi — dopo che hai finito le settimanali correnti.",
	PROFACAD_CH_WEEKLY_TASK = "Prendi la quest introduttiva da Captain Flaresworn e fai la tua prima settimanale dell'addestratore.",
	PROFACAD_CH_WORKORDERS_TITLE = "Work Orders (Crafting Orders) spiegati",
	PROFACAD_CH_WORKORDERS_BODY = "Un Work Order (Crafting Order) è una richiesta 'su misura': qualcuno vuole un oggetto craftato e un giocatore con quella professione lo realizza. Il Crafting Order table si trova nel Silvermoon Bazaar, vicino a Captain Flaresworn.\n\nCe ne sono di quattro tipi:\n\n|cffffcc001. Patron Orders|r - piazzati da NPC (non serve nessun altro giocatore). SEI TU a craftarli per ottenere ricompense: Moxie, ricette e Knowledge Points. È la principale fonte settimanale di Knowledge per i crafter - fai ogni settimana quelli con l'icona Knowledge.\n\n|cffffcc002. Public Orders|r - ordini di qualsiasi giocatore, che qualsiasi crafter può prendere. Chi ordina fornisce TUTTI i materiali. Come crafter puoi fare fino a 4 public order al giorno e hai 30 minuti per completarne uno dopo averlo preso.\n\n|cffffcc003. Personal Orders|r - rivolti a una persona specifica (es. chiedi a un compagno di gilda di craftare per te). Il crafter può aggiungere da sé eventuali materiali mancanti.\n\n|cffffcc004. Guild Orders|r - all'interno della tua gilda; funzionano tra reami diversi.\n\n|cffffcc00Come COMPRARE qualcosa di craftato|r (vuoi un oggetto ma non sai craftarlo): apri il Crafting Order table, scegli l'oggetto e piazza un Public o Personal order. Di solito fornisci tu i materiali (più una mancia) e un crafter lo completa - puoi anche richiedere una qualità minima.\n\n|cffffcc00Come CRAFTARE per gli altri|r (guadagna oro): al tavolo, prendi un Public Order per una ricetta che conosci, procurati i materiali elencati, craftalo e vieni pagato. Ti servono la professione, la ricetta e la skill giuste per completare un ordine.\n\n|cffffcc00Consiglio per principianti|r: all'inizio ignora Public/Personal/Guild. Quello che conta presto sono i Patron Orders - il tuo motore settimanale di Knowledge.",
	PROFACAD_CH_WORKORDERS_TASK = "Visita il Crafting Order table nel Silvermoon Bazaar e apri la scheda Patron Orders.",
	PROFGUIDE_LVL_ALCHEMY = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Camberon a Silvermoon City; il supply vendor Melaris sta accanto a lui (Sunglass Vials, Oil of Heartwood).|n• Si abbina al meglio con l'Herbalism così farmi le tue erbe; altrimenti comprale all'Auction House.|n|n|cffffcc00Lista della spesa 1-50|r (va bene la qualità più economica): ~300 Tranquility Bloom, 15 Sanguithorn, 12 Mote of Light, 4 Argentleaf, 4 Mote of Primal Energy, 3 Mana Lily, più Sunglass Vials da Melaris.|n|n|cffffcc00Il percorso|r|n• 1-7: crafta 6x Silvermoon Health Potion.|n• 7-20: usa Recycle Potions 10x sulle pozioni che hai appena fatto.|n• 20-27: al Camberon's Cauldron (accanto al trainer) ricerca Primal Philosopher's Stone + Lightfused Mana Potion, poi fai il first-craft delle nuove ricette (ogni first craft = +1 Knowledge).|n• 25: qui si sblocca la tua prima specializzazione.|n• 27-50: crafta Entropic Extract, poi altre Silvermoon Health Potions.|n• 50-100: crafta le pozioni Light's Potential, oppure i flask se hai la spec flask, o le trasmutazioni - qualunque cosa sia più economica sul tuo reame.|n|n|cffffcc00Consiglio|r: il Camberon's Cauldron è un oggetto di ricerca accanto al trainer - non è casuale. Scegli tu cosa sbloccare e paghi un po' di Moxie. Non saltarlo.",
	PROFGUIDE_LVL_HERBALISM = "|cffffcc00Skill leveling 1-100 (raccogliendo)|r|n• Trainer: Botanist Nathera a Silvermoon City. L'Herbalism sale raccogliendo erbe, non craftando.|n• Inizia in Eversong Woods - il terreno più facile e meno mob. Poi visita le altre zone per varietà e bonus Knowledge di first-gather.|n|n|cffffcc00Intervalli di skill|r|n• 1-30: quasi tutto dà skill - raccogli ciò che trovi.|n• 30-60: le quattro erbe base (Sanguithorn, Azeroot, Argentleaf, Mana Lily) danno ancora skill; la Tranquility Bloom si ferma a 30.|n• 60-100: solo le varianti Lush e Infused danno skill - compaiono casualmente al posto delle erbe normali, quindi continua a raccogliere.|n|n|cffffcc00Rendilo fluido|r|n• Bevi Azeroot Tea (+Deftness) e Darkmoon Firewater - quasi obbligatori così i mob non ti interrompono mentre raccogli.|n• Sul tuo Sickle punta a Finesse o Deftness; ottieni abbastanza Deftness da raccogliere senza combattere.|n|n|cffffcc00Erbe Infused e Overloading|r|nLe erbe luminose danno motes extra ma ti infliggono un piccolo debuff. Dopo la tua prima raccolta infused impari Overload Infused Herb (lo trovi nella scheda General dello spellbook, non in quella delle professioni). Cooldown 12h, ridotto di 30 min per ogni erba raccolta (~24 erbe per resettarlo del tutto). Usalo sui nodi Lightfused/Wild/Primal/Voidbound per motes bonus - ma salta Primal se sei sotto il 50% di HP (il channel può ucciderti).",
	PROFGUIDE_LVL_ENCHANTING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Dolothos a Silvermoon City; il supply vendor Lyna sta accanto a lui (Enchanting Vellum, Refulgent Copper Rods). Disincanta prima ogni equipaggiamento di scorta - dà skill fino a 25.|n|n|cffffcc00Lista della spesa 1-62|r: ~412 Eversinging Dust, 27 Radiant Shard, 6 Mote of Light (recuperi polvere disincantando i rod, quindi potrebbe servirtene meno).|n|n|cffffcc00Il percorso|r|n• 1-25: crafta 30x Runed Refulgent Copper Rod, poi disincanta tutti e 30 per skill.|n• 25-40: fai il first-craft di Enchant Helm - Rune of Avoidance, Thalassian Phoenix Oil, Enchant Ring - Nature's Wrath, poi ~13 altri Nature's Wrath, più Flight of the Eagle e Hex of Leeching.|n• 40-52: crafta 4x Thalassian Spellweaver's Wand (3 skill ciascuno).|n• 52-62: anelli Amani Mastery più qualche enchant per helm/shoulder; il metodo rush spamma Enchant Ring - Amani Mastery fino a 70.|n• 62-100: crafta una di ogni ricetta che possiedi, poi qualsiasi cosa si venda; Enchant Weapon - Worldsoul Aegis resta arancione fino a 100 come ripiego.|n|n|cffffcc00Consiglio|r: fai la deviazione Gleeful Glamours - imparale tutte e 24 da Jennara Sunglow a 39.5, 51.0 a Lunargenta, ultimo piano per +24 Knowledge. Scegli una specializzazione intorno a 60, non allo sblocco a 25.",
	PROFGUIDE_LVL_TAILORING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Galana a Silvermoon City; il supply vendor accanto a lei vende Silverleaf Thread, Embroidery Floss e le ricette Elegant Artisan (per l'Artisan Tailor's Moxie).|n|n|cffffcc00Lista della spesa 1-50|r: 66 Bright Linen, 14 Eversinging Dust.|n|n|cffffcc00Il percorso|r|n• 1-25: crafta 66x Bright Linen Bolt - tienili tutti, ti servono per ricette successive anche dopo che diventano grigi.|n• 25-40: crafta 14x Imbued Bright Linen Bolt.|n• 40-45: attiva il filtro \"First Craft Bonus\" e crafta una volta ogni ricetta rimanente; equipaggia la Bright Linen Tailoring Robe.|n• 44-50: crafta 6x Courtly Shoulders.|n• 50-100: meglio farlo con calma - spendi 5 punti in Nimble Needlework per sbloccare un CD giornaliero di bolt (Sunfire Silk Bolt o Arcanoweave Bolt) e livella con quello. Per fare rush: Bright Linen Spellthread (50-65), Sunfire Silk/Arcanoweave Lining (65-90), poi oggetti Elegant Artisan come il Cooking Hat (90-100).|n|n|cffffcc00Consiglio|r: la tua prima specializzazione si sblocca a skill 25. Il Tailoring è lento a raggiungere la qualità Gold garantita, quindi c'è poco motivo di fare rush - il percorso del CD giornaliero fa anche oro.",
	PROFGUIDE_LVL_LEATHERWORKING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Talmar a Silvermoon City; il supply vendor accanto a lui vende Silverleaf Thread.|n|n|cffffcc00Lista della spesa (fino a skill 60)|r: ~690 Void-Tempered Leather, ~610 Void-Tempered Scales, 3 Void-Tempered Hide, 2 Void-Tempered Plating, 4 Peerless Plumage, 3 Carving Canine, 4 Fantastic Fur, 10 Tranquility Bloom, 4 Mote of Light, 1 Mote of Pure Void, 75 Silverleaf Thread.|n|n|cffffcc00Il percorso|r|n• 1-7: fai il first-craft di Smuggler's Leather Wristbands e Scout's Scaled Bracers, poi torna dal trainer.|n• 7-60: attiva il filtro \"First Craft Bonus\", crafta una volta ogni ricetta, impara nuove ricette dal trainer ogni 5-10 skill, ripeti fino al batch di skill 50 (~61); equipaggia la Hideworker's Cover.|n• 60-91: crafta ~35x di una qualsiasi tra Blessed Pango Charm, Primal Spore Binding, Blood Knight's Armor Kit, Forest Hunter's Armor Kit o Devouring Banding.|n• 91-100: continua, oppure passa a una qualsiasi ricetta di armatura leather/mail epica (3 skill ciascuna, servono solo 3 craft) tramite i crafting order.|n|n|cffffcc00Consiglio|r: la tua prima specializzazione si sblocca a skill 25. Se Fantastic Fur, Peerless Plumage o Carving Canine costano cari all'AH, crafta semplicemente un'altra ricetta arancione che dà più punti skill.",
	PROFGUIDE_LVL_BLACKSMITHING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Bemarrin a Silvermoon City; il supply vendor accanto a lui vende Luminant Flux, Blacksmith Hammer e le ricette di equipaggiamento epico (per l'Artisan Blacksmith's Moxie). Si abbina al meglio con il Mining così farmi il tuo ore.|n|n|cffffcc00Lista della spesa 1-50|r: 125 Refulgent Copper Ore, 100 Refulgent Copper Ingot (o 500 ore extra da fondere da te), 6 Brilliant Silver Ore, 6 Umbral Tin Ore, 1 Duskshrouded Stone. Per 50-70: 300 Brilliant Silver Ore più 150 ingot in più.|n|n|cffffcc00Il percorso|r|n• 1-15: fondi 25x Refulgent Copper Ingot.|n• 15-50: attiva il filtro \"First Craft Bonus\", crafta una volta ogni ricetta, impara nuove ricette dal trainer e ripeti per tutte e 28; equipaggia il Thalassian Blacksmith's Toolbox e l'Hammer.|n• 50-70: crafta 50x Sterling Alloy.|n• 70-100: fai rush con l'equipaggiamento raro di professione tramite la spec Craftsmithing (1 skill ciascuno, niente mat a tempo), oppure usa equipaggiamento epico / crafting order (3 skill ciascuno, ~10 per finire).|n|n|cffffcc00Consiglio|r: la tua prima specializzazione si sblocca a skill 25. I rari tool Sun-Blessed (Pickaxe, Hammer, Skinning Knife) sono BoE, quindi puoi vendere quelli che fai mentre livelli.",
	PROFGUIDE_LVL_ENGINEERING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Danwe a Silvermoon City; il supply vendor accanto a lui vende Malleable Wireframe, Pile of Junk, Arclight Spanner e Gyromatic Micro-Adjustor.|n|n|cffffcc00Lista della spesa (ogni ricetta del trainer una volta)|r: 145 Refulgent Copper Ore, 155 Umbral Tin Ore, 135 di un reagente di recycle economico (Powder Pigment, Refulgent Copper Ingot o Bright Linen Bolt), 21 Malleable Wireframe, 35 Pile of Junk, più 1 ciascuno di Mote of Light/Primal Energy/Wild Magic/Pure Void.|n|n|cffffcc00Il percorso|r|n• 1-16: crafta 8x Song Gear, poi 7x Recycling.|n• 16-39: fai il first-craft degli oggetti Evercore (Shade, Vision Guard, Dome Dinger, Zoomshroud, Reconissance), scegli Recycling come prima spec, poi crafta 10x Soul Sprocket e i quattro Cogwheels.|n• 39-45: 20x Recycling, poi fai il first-craft di ogni nuova ricetta bonus.|n• 45-80: Recycle finché non scopri una ricetta Quel'dorei, poi crafta in massa equipaggiamento Quel'dorei (es. 60x Quel'dorei Guards).|n• 80-100: crafta Housing Decor (l'unico percorso a 100 senza order), equipaggiamento raro, o tool/armatura epici tramite crafting order.|n|n|cffffcc00Consiglio|r: la scoperta del Recycling è bloccata di default - metti prima 10 punti nella spec Recycling o le ricette Quel'dorei economiche non compaiono mai. I punti non sono sprecati; aggiungono anche skill di crafting.",
	PROFGUIDE_LVL_INSCRIPTION = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Zantasia a Silvermoon City; il supply vendor vicino a lei vende Thalassian Songwater e Lexicologist's Vellum.|n|n|cffffcc00Lista della spesa 1-100|r: 360 Tranquility Bloom, 100 Argentleaf, 90 Mana Lily, 90 Sanguithorn, 65 Azeroot, 1 Duskshrouded Stone, 1 Mote of Light, 4 Mote of Primal Energy, 7 Mote of Wild Magic, 4 Mote of Pure Void.|n|n|cffffcc00Il percorso|r|n• 1-20: usa Midnight Milling su tutte le tue erbe.|n• 20-30: crafta 11x Munsell Ink poi 12x Sienna Ink - tienili. A 25 impara Calm Hands come prima spec (insegna la ricetta Treatise).|n• 30-45: fai il first-craft dei baton, Soul Cipher e Missives tramite il filtro \"First Craft Bonus\", poi fino a 3x Thalassian Treatise on Inscription.|n• 45-100: continua a craftare Thalassian Treatise on Inscription (~70 in totale) - scopri i Treatise per le altre professioni man mano, quindi fai il first-craft di ciascuno per skill bonus.|n|n|cffffcc00Consiglio|r: comprare gli inchiostri direttamente dall'Auction House è di solito più veloce ed economico che macinare i pigmenti. Non usare il consumabile Treatise finché non hai deciso la tua spec - 10 punti in Calm Hands lo trasformano in 2 Knowledge.",
	PROFGUIDE_LVL_JEWELCRAFTING = "|cffffcc00Skill leveling 1-100 (veloce ed economico)|r|n• Trainer: Amin a Silvermoon City; il supply vendor accanto a lui vende il Jeweler's Toolset. Si abbina al meglio con il Mining così farmi il tuo ore e le tue gem.|n|n|cffffcc00Lista della spesa (ogni ricetta del trainer una volta)|r: 60 ore economico (Refulgent Copper/Umbral Tin/Brilliant Silver), 31 Glimmering Gemdust, 100 Crystalline Glass, 7 Duskshrouded Stone, 5 Sanguine Garnet, 4 ciascuno di Tenebrous Amethyst/Harandar Peridot/Amani Lapis, più un Flawless di ogni gem.|n|n|cffffcc00Il percorso|r|n• 1-14: 12x Midnight Prospecting, poi crafta 4x Sin'dorei Lens.|n• 14-50: attiva il filtro \"First Craft Bonus\" e crafta una volta ogni ricetta del trainer, imparandone di nuove ogni 5 skill.|n• 50-65: crafta 40x Monologuer's Chalice (molto economico).|n• 65-100 (opzionale): taglia Eversong Diamonds (2 skill ciascuno), spamma equipaggiamento di professione raro/epico da Gelanthis, o completa crafting order di gioielleria se sei speccato per ring/necklace.|n|n|cffffcc00Consiglio|r: la tua prima specializzazione si sblocca a skill 25. Tieni il trainer e la finestra della professione aperti fianco a fianco per il tratto 14-50 - nuove ricette arrivano ogni 5 skill e un first-craft di ciascuna ti tiene in pari.",
	PROFGUIDE_LVL_MINING = "|cffffcc00Skill leveling 1-100 (raccogliendo)|r|n• Trainer: Belil a Silvermoon City. Il Mining sale minando i nodi deposit, non craftando.|n• Inizia in Eversong Woods - il terreno più facile e la minor densità di mob. Poi visita Zul'Aman, Harandar e Voidstorm per varietà e Knowledge di first-gather.|n|n|cffffcc00Intervalli di skill|r|n• 1-30: quasi ogni deposit dà skill - mina ciò che trovi.|n• 30-60: i deposit base diventano gialli a 30; i Rich deposit, le Seam e le varianti Infused danno ancora skill.|n• 60-100: i deposit base sono grigi - solo i Rich deposit, le Seam e le varianti Infused danno skill, comparendo casualmente al posto di quelli normali.|n|n|cffffcc00Rendilo fluido|r|n• Bevi Azeroot Tea (+Deftness) e Darkmoon Firewater - i nodi richiedono un po' di channel, quindi è praticamente obbligatorio.|n• Sulla tua Pickaxe punta a Deftness o Finesse; ottieni abbastanza Deftness da minare senza combattere.|n|n|cffffcc00Deposit Infused e Overloading|r|nI deposit luminosi danno motes extra ma applicano un debuff. La tua prima estrazione Infused insegna Overload (scheda General dello spellbook, non quella delle professioni). Cooldown 12h, ridotto di 30 min per deposit minato (~24 per resettarlo del tutto). Usalo sui nodi Lightfused/Wild/Primal/Voidbound - ma salta Primal sotto il 50% di HP (il channel può ucciderti) e non sprecarlo sui Wild deposit di Zul'Aman.",
	PROFGUIDE_LVL_SKINNING = "|cffffcc00Skill leveling 1-100 (raccogliendo)|r|n• Trainer: Tyn a Silvermoon City. Lo Skinning sale scuoiando bestie, non craftando.|n• Farma Void-Tempered Leather dai mob di pelle e Void-Tempered Scales in Eversong Woods (Agitated Wyrms, Territorial Dragonhawks); pelliccia, piumaggio e zanne arrivano dalle creature corrispondenti.|n|n|cffffcc00Come funziona|r|nNon c'è una tabella numerica in stile Classic - la skill di skinning scala attraverso gli alberi di specializzazione, alimentata dai Knowledge Points. Tre alberi: Thorough Tanning (più leather/scales), Gainful Gathering (motes e mat unici) e Talented Tracker (lures e Renowned Beasts).|n|n|cffffcc00Build da puro farming|r|n• 0-80 punti: 10 in Thorough Tanning, poi Lasting Leather o Superb Scales (40), poi 30 di nuovo in Thorough Tanning.|n• 80-130 punti: 10 in Gainful Gathering, poi Careful Carving o Trophy Taker (40).|n|n|cffffcc00Consigli|r|n• Le High Value Beasts mostrano un'icona luminosa di skinning-knife sulla minimappa e danno 5-10 hide extra - il tracking è attivo di default.|n• Porta due coltelli: Finesse per più materiali base, Perception per un tiro extra sui rari - passa a Perception quando usi Sharpen Your Knife o scuoi Renowned Beasts. Abbina i tuoi consumabili (Argentleaf Tea / Sanguithorn Tea) al coltello.",
	PROFACAD_CH_ENCHANTING_TITLE = "Guida iniziale Enchanting",
	PROFACAD_CH_ENCHANTING_BODY = "L'Enchanting è quello diverso dagli altri: guadagni la maggior parte dei KP settimanali disincantando equipaggiamento. Ogni settimana le prime 5 Swirling Arcane Essences danno +1 KP ciascuna, poi un Brimming Mana Shard dà +4 — sono +9 KP a settimana solo per frantumare il loot. L'Enchanting non riceve patron order.\n\nBuild iniziale (consenso della community): prima Spellbound Shatterer (il suo buff Shatter Essence aumenta le tue stat di crafting), poi Elevating Equipment — root a ~30, poi il ramo Weapon/Ring/Chest (gli enchant più richiesti). Disenchanting Delegate è un ottimo terzo per l'autosufficienza di materiali.\n\nLibri KP extra: renown 6 della Silvermoon Court, e il vendor dell'evento Abundance (Chel the Chip) vende anche un libro di Enchanting.",
	PROFACAD_CH_ENCHANTING_TASK = "Disincanta equipaggiamento finché non hai le 5 Essences + il Mana Shard di questa settimana (+9 KP).",
	PROFACAD_CH_ALCHEMY_TITLE = "Guida iniziale Alchemy",
	PROFACAD_CH_ALCHEMY_BODY = "Gli alberi dell'Alchemy si sbloccano a skill 25/50/60/75: Potion Prowess (pozioni, split Light/Void), Fluent in Flasks (flask, phial e un cauldron di gruppo), Transmutation Authority e Alchemical Mastery.\n\nBuild iniziale: metti i primi 20-30 KP in Fluent in Flasks o Potion Prowess — quelle ricette sono ciò che raider e giocatori M+ comprano tutto l'anno. Transmute e Mastery vengono dopo.\n\nIl primo giorno può essere esplosivo: i primi craft più i tesori una tantum valgono circa 40-50 KP. I Patron Order (bacheca degli ordini di crafting) sono il tuo motore KP settimanale — falli ogni settimana. Il libro KP renown sta a The Singularity renown 9.",
	PROFACAD_CH_ALCHEMY_TASK = "Fai i tuoi Patron Order disponibili questa settimana (bacheca degli ordini di crafting).",
	PROFACAD_CH_TAILORING_TITLE = "Guida iniziale Tailoring",
	PROFACAD_CH_TAILORING_BODY = "I tailor sono l'unica fonte di armatura cloth craftata — e dei bolt (Arcanoweave e Sunfire Silk) che alimentano borse, equipaggiamento embellished e spellthread. Quei bolt sono dietro un cooldown giornaliero che solo i tailor specializzati sbloccano: motivo sufficiente per speccare con cura.\n\nBuild iniziale: metti i primi ~30 punti nel root Nimble Needlework (skill e stat per armatura E bolt), poi scegli il tuo focus. Armatura: Sin'dorei Finery — scegli UN gruppo di slot (es. vesti/pantaloni/mantelli) e massimizzalo prima di iniziarne un altro. Bolt/oro: Sunfire Silk Weaving o Arcanoweaving più il suo nodo Expertise (più bolt, cooldown più corto).\n\nFiber Arts e Fabric Specialist migliorano ogni craft (e i tuoi drop di cloth in zone specifiche) — buon riempitivo per i punti in eccesso.",
	PROFACAD_CH_TAILORING_TASK = "Sblocca un bolt tramite Nimble Needlework e crafta il tuo cooldown del bolt oggi.",
	PROFACAD_CH_LEATHERWORKING_TITLE = "Guida iniziale Leatherworking",
	PROFACAD_CH_LEATHERWORKING_BODY = "I leatherworker sono l'unica fonte SIA di leather SIA di mail craftato — due alberi separati, quindi scegli prima un tipo di armatura. Learned Leatherworker è l'albero dei fondamentali e abbassa persino il costo di Concentration per craft.\n\nBuild iniziale: prima Lasting Leather (leather) OPPURE Safeguarding Scales (mail), massimizzando un sotto-nodo di slot alla volta, poi Learned Leatherworker. Flawless Fortes viene dopo: strumenti di professione da un lato, consumabili (armor kit, drum) dall'altro — quelli si vendono con costanza.",
	PROFACAD_CH_LEATHERWORKING_TASK = "Scegli leather o mail e massimizza il tuo primo sotto-nodo di slot.",
	PROFACAD_CH_BLACKSMITHING_TITLE = "Guida iniziale Blacksmithing",
	PROFACAD_CH_BLACKSMITHING_BODY = "I blacksmith sono l'unica fonte di equipaggiamento plate craftato, più weaponstone, tool stone e leghe. The Old Ways è il tuo albero dei fondamentali (Ingenuity, Multicraft, Resourcefulness per TUTTI i craft) — alimentalo insieme a qualsiasi cosa scegli.\n\nPoi scegli un focus: Armorsmithing (diviso per gruppo di slot) o Weaponsmithing (diviso per tipo di arma) — massimizza UN sotto-nodo completamente prima di iniziarne un altro. Craftsmithing crea equipaggiamento di professione per altre sei professioni. Leghe, weaponstone e tool stone si vendono con costanza senza crafting order.",
	PROFACAD_CH_BLACKSMITHING_TASK = "Scegli il tuo albero di focus (Armorsmithing o Weaponsmithing) e massimizza prima un sotto-nodo.",
	PROFACAD_CH_ENGINEERING_TITLE = "Guida iniziale Engineering",
	PROFACAD_CH_ENGINEERING_BODY = "Gli engineer sono gli unici fornitori di gun e craftano goggle (solo per engineer), bracer e boot — più gadget e scope. Recycling è l'albero dei fondamentali: skill su TUTTI i craft, e restituisce materiali mentre lavori.\n\nDopo Recycling, scegli un albero e massimizza prima un singolo nodo. Attenzione: in Bits and Bots i nomi ingannano — Bits sono reagenti/cogwheel (scope), Bots sono reagenti opzionali e gadget. Scope, attacchi per gli stivali e gadget sono venditori affidabili all'auction house.",
	PROFACAD_CH_ENGINEERING_TASK = "Metti i primi punti in Recycling, poi scegli il tuo albero di focus.",
	PROFACAD_CH_INSCRIPTION_TITLE = "Guida iniziale Inscription",
	PROFACAD_CH_INSCRIPTION_BODY = "Gli scriba craftano staff, archi, off-hand, missive (stat sull'equipaggiamento craftato), Vantus rune e carte Darkmoon. Vantaggio unico: massimizzare il nodo centrale Calm Hands sblocca il Thalassian Treatise settimanale — +2 KP ogni settimana, l'unica professione con questo.\n\nQuindi: prima Calm Hands, sempre. Poi Blueprints (equipaggiamento), Perfected Products (consumabili) o Darkmoon Curiosity (carte, diviso per tipo di carta). Vantus rune, missive e inchiostri si vendono con costanza.",
	PROFACAD_CH_INSCRIPTION_TASK = "Lavora per massimizzare il nodo centrale Calm Hands (Treatise settimanale = +2 KP/settimana).",
	PROFACAD_CH_JEWELCRAFTING_TITLE = "Guida iniziale Jewelcrafting",
	PROFACAD_CH_JEWELCRAFTING_BODY = "I jewelcrafter sono l'unica fonte di anelli e collane craftati — servono a tutti. Il Prospecting trasforma il minerale in gemme; il crushing trasforma le gemme in eccesso in Gemdust. Consiglio: non spendere mai Concentration su prospecting o crushing.\n\nInizia con Thoughtful Throughput (fondamentali), poi nota due scorciatoie: serve solo il nodo centrale Glamorous Gems per tagliare gli Eversong Diamonds alla massima qualità, e Proficient Processor (prospecting/crushing) è economico da completare. Gemme tagliate e reagenti come Sunglass Vial si vendono bene.",
	PROFACAD_CH_JEWELCRAFTING_TASK = "Sblocca il nodo centrale Glamorous Gems e taglia la tua prima gemma di qualità.",
	PROFACAD_CH_HERBALISM_TITLE = "Guida iniziale Herbalism",
	PROFACAD_CH_HERBALISM_BODY = "Ogni erba spawna in ogni zona, quindi niente stress nella scelta della zona. Il grande sblocco è raccogliere mentre sei a cavallo: metti i primi ~40 punti nel root Botany per quello (i Druid lo saltano — raccolgono già a cavallo — e vanno dritti a Bountiful Harvests).\n\nPoi ~40 in Bountiful Harvests (più erbe per nodo, più skill = più qualità top), e dopo bonus per-erba su qualsiasi cosa si venda meglio. Erbe speciali infuse (Lightfused, Wild, Primal, Voidbound) possono essere Overloaded per un mucchio di mote — la prima volta per tipo di erba concede persino un Knowledge Point. Il cooldown di 12 ore cala di ~30 minuti per ogni nodo che raccogli, e 40 punti root aggiungono una seconda carica.",
	PROFACAD_CH_HERBALISM_TASK = "Sblocca la raccolta a cavallo tramite il root Botany (salta se sei Druid).",
	PROFACAD_CH_MINING_TITLE = "Guida iniziale Mining",
	PROFACAD_CH_MINING_BODY = "Tutti i minerali appaiono in tutte le zone. Primo obiettivo: ~40 punti nel root Meticulous Mining per minare mentre sei a cavallo — il più grande sblocco di quality-of-life in Midnight. Poi ~50 nel root Plentiful Ores per skill su ogni minerale.\n\nDopodiché, riempi i singoli nodi dei minerali (distribuisci in modo uniforme a meno che un minerale non sia molto più costoso); massimizzare un minerale aumenta i drop di Dazzling Thorium da esso. Depositi speciali infusi (Lightfused, Wild, Primal, Voidbound) possono essere Overloaded per un mucchio di mote — la prima volta per tipo di minerale concede un Knowledge Point. Il cooldown di 12 ore cala di ~30 minuti per ogni nodo che mini, 40 punti root aggiungono una seconda carica, e l'albero Over-LODED lo potenzia ulteriormente. Il Refulgent Copper è sempre richiesto.",
	PROFACAD_CH_MINING_TASK = "Sblocca il mining a cavallo tramite il root Meticulous Mining.",
	PROFACAD_CH_SKINNING_TITLE = "Guida iniziale Skinning",
	PROFACAD_CH_SKINNING_BODY = "Gli skinner alimentano i leatherworker — e Midnight ti dà strumenti per farlo: le bestie di alto valore appaiono sulla minimappa, i Diffuser estraggono mote dai mob, e i Majestic Lure (Talented Tracker) evocano una bestia di zona una volta al giorno che droppa materiali epici.\n\nBuild iniziale (farming): qualche punto nel root Thorough Tanning, poi massimizza il ramo leather o scales, poi di nuovo nel root. Poi Gainful Gathering: Careful Carving (Finesse, farming di massa) o Trophy Taker (Perception, rare). Cambia strumenti di conseguenza: Finesse per il volume, Perception per i rare.",
	PROFACAD_CH_SKINNING_TASK = "Massimizza il ramo leather o scales in Thorough Tanning e scuoia con lo strumento corrispondente.",
	TAB_DELVE_LOG = "Delve & Ritual Log",
	DELVELOG_SUBTITLE = "Un registro per personaggio di ogni delve e ritual run di Midnight che completi: tier, tempo, morti e (per le delve) la key usata e il boss finale. Tracciato automaticamente — non serve tenerlo aperto.",
	DELVELOG_EMPTY = "Ancora nessuna delve run registrata. Completa una delve di Midnight per iniziare il tracciamento.",
	DELVELOG_SEC_RITUALS = "Rituals",
