	-- Consumable ready check (/mh readycheck, auto on dungeon entry)
	CONSREADY_HEADER_FMT = "Controllo consumabili — %s",
	CONSREADY_HEADER = "Controllo consumabili",
	CONSREADY_YOU = "Tu",
	CONSREADY_FLASK = "Flask",
	CONSREADY_RUNE = "Augment Rune",
	CONSREADY_CPOT = "Pozione combat",
	CONSREADY_HPOT = "Pozione cura",
	CONSREADY_HS = "Healthstone",
	CONSREADY_FOOD = "Cibo",
	CONSREADY_ALT = " (alt)",
	CONSREADY_TEST_SENT = "Test: stato delle tue borse inviato a te stesso — guarda la riga di ricezione.",
	CONSREADY_TEST_RECV = "Test ricevuto: Flask %d · Rune %d · Pozione combat %d · Pozione cura %d · Cibo %d · Healthstone %d. Pipeline comms OK.",
	CONSREADY_BOARD_HINT = "Trascina per spostare · si nasconde al pull · /mh readycheck per la chat",
	CONSREADY_USE_HINT = "Clicca per usare",
	CONSREADY_NOT_IN_BAG = "Non nelle tue borse",
	CONSREADY_CAST_HINT = "Clicca per lanciare",
	CONSREADY_HAS = "Ha:",
	CONSREADY_MISSING = "Manca:",
	CONSREADY_BUFF = "buff",
	CONSREADY_BAG_UNKNOWN = "borsa sconosciuta",
	CONSREADY_FOOTER = "|TInterface/RAIDFRAME/ReadyCheck-Ready:0|t presente/attivo · |TInterface/RAIDFRAME/ReadyCheck-NotReady:0|t mancante · |TInterface/RAIDFRAME/ReadyCheck-Waiting:0|t sconosciuto. I membri del gruppo mostrano solo lo stato dei buff — l'API non può leggere le borse altrui (la condivisione delle borse arriva nella Fase 2). /mh readytoggle per silenziare.",
	CONSREADY_TOGGLE_ON = "Controllo consumabili ATTIVO (auto all'ingresso nel dungeon).",
	CONSREADY_TOGGLE_OFF = "Controllo consumabili DISATTIVO.",
	CONSREADY_BOARDALL_SENT = "Chiesto ai membri del gruppo con Midnight Helper di riaprire il pannello consumabili.",
	CONSREADY_BOARDALL_NOTLEAD = "Solo il leader del gruppo (o l'assistente) può riaprire il pannello per tutti.",
	CONSREADY_BOARDALL_NOGROUP = "Non sei in un gruppo.",
	CONSREADY_API_MISSING = "non disponibile su questo client",
	AURADUMP_HEADER = "I tuoi buff attivi (spellID — nome):",
	AURADUMP_NONE = "Nessun buff attivo.",
	AURADUMP_DEBUFF_HEADER = "I tuoi debuff attivi (spellID — nome):",
	TAB_ENCHANTS = "Enchant & Gemme",
	ENCHANT_SUBTITLE = "Un controllo rapido del tuo equipaggiamento: slot incantabili senza enchant, oltre a oggetti con castoni vuoti — ciascuno con un suggerimento Midnight abbinato alle stat per la tua spec. Si aggiorna man mano che cambi gear.",
	INFO_DRAWER_BODY_ENCHANTS = "Scansiona i tuoi slot incantabili (arma, petto, elmo, spalle, anelli, stivali, gambe) e segnala quelli senza enchant. Anelli e arma ricevono un suggerimento in base alla migliore stat secondaria della tua spec (dai pesi del Vault Advisor); petto, gambe e slot terziari sono generici. Per il puro best-in-slot, controlla una guida di classe. Mantello, polsi e cintura non sono incantabili in questa patch. Controlla anche i castoni vuoti: un Diamante Thalassiano unico (+32 stat principale — uno solo) più una gemma doppia adatta alle tue stat negli altri castoni.",
	TAB_CURRENCY = "Currencies",
	CURRENCY_QM_LABEL = "Waypoint Renown Quartermaster:",
	CURRENCY_QM_COURT = "SMC Court",
	CURRENCY_QM_AMANI = "Amani",
	CURRENCY_QM_HARATI = "Hara'ti",
	CURRENCY_QM_SINGULARITY = "Singularity",
	TAB_TIER = "Tier Sets",
	TIER_SUBTITLE = "Cosa sono i tier set, come ottenerli, e i bonus del tuo set con un tracker 2-set / 4-set in tempo reale.",
	INFO_DRAWER_BODY_TIER = "Spiega i tier set di Midnight: i 5 slot del set, i bonus da 2 e 4 pezzi, e come ottenerli (token di raid, il Great Vault, il Matrix Catalyst). Mostra il set della tua classe con link ai bonus cliccabili e conta quanti pezzi tier hai equipaggiati. I valori dei bonus set sono datamined per la 12.0.7 — passa il mouse su un link per la tooltip in tempo reale.",
	TIER_GUIDE_BODY = "|cffe8c36aCosa sono i tier set|r|n• 5 slot speciali — testa, spalle, petto, mani, gambe — che danno un bonus a 2 e 4 pezzi. Il 4-set è di solito un grosso aumento di potere, quindi è normalmente il tuo primo obiettivo (spesso vale più di qualche item level).|n• Ti servono solo 4 dei 5; lascia lo slot in cui hai il tuo oggetto non-tier più forte. Polsi, cintura, stivali, collo, anelli, mantello e armi non sono mai tier — prendi sempre il miglior upgrade grezzo lì.|n|n|cffe8c36aCome ottenerli|r|n• Drop di raid: i boss 2–5 di The Voidspire droppano ciascuno un token di classe (mani, spalle, gambe, elmo). Il pezzo del petto viene da The Dreamrift.|n• Great Vault: sconfiggi 2/4/6 boss di raid in una settimana per sbloccare le scelte del vault.|n• {CATALYST} (Silvermoon): converte un pezzo non-set idoneo (testa/spalle/petto/mani/gambe) nello slot tier che ti serve. Sbloccalo una volta da Eldara Dawnrunner (quest 'Taste True Power'); ogni conversione spende un Dawnlight Manaflux. Ottieni la prima carica nella settimana 1, poi un'altra ogni 2 settimane. Una volta raggiunto il 4-set, le cariche iniziano anche a droppare da raid, M+, Bountiful Delves e PvP rated.|n|n|cffe8c36aPercorso per nuovi giocatori|r|n• Fai LFR Voidspire ogni settimana per tentativi sui token, riempi il tuo Great Vault, e spendi una carica del Catalyst sullo slot che ti manca. La maggior parte dei giocatori raggiunge il 2-set in fretta (un drop + un Catalyst), poi completa il 4-set dal Vault o da una seconda carica del Catalyst.",
	TIER_YOUR_SET = "Il tuo set:",
	TIER_2SET = "Bonus 2 pezzi:",
	TIER_4SET = "Bonus 4 pezzi:",
	TIER_COUNT_FMT = "Pezzi tier equipaggiati: %d/5",
	TIER_COUNT_UNKNOWN = "Equipaggia un pezzo tier per tracciare qui il tuo progresso 2-set / 4-set.",
	TIER_SET_UNKNOWN = "(il bonus set della tua spec non è ancora mappato — controllalo in gioco)",
	TIER_FOOTER = "I valori dei bonus set sono datamined per la 12.0.7 e ancora in fase di bilanciamento — passa il mouse su un link per la tooltip in tempo reale e conferma in gioco.",
	TIER_CATALYST_NAME = "Matrix Catalyst",
	CURRENCY_SUBTITLE = "Dove si guadagna, dove si spende: una mappa rapida di ogni valuta di Midnight e quale vendor la accetta.",
	INFO_DRAWER_BODY_CURRENCY = "Elenca ogni valuta di Midnight: come la guadagni e quale vendor la accetta. Clicca il nome di una valuta per aprire il tuo totale in tempo reale. I crest di potenziamento hanno la loro tab con la scala completa.",
	CURRENCY_GUIDE_BODY = "|cffe8c36aVoidlight Marl|r — {CURRENCY:3316}|n• Guadagnalo da: rare, world quest, delve, cacce Prey, Ritual Sites e il loro paragon cache.|n• Spendilo da: i quattro Renown Quartermaster nelle zone (elencati sotto), più i vendor di cavalcature/pet/cosmetici e casa. Trasferibile tra i tuoi personaggi (warband).|n|n|cffe8c36aField Accolade|r — {CURRENCY:3405}|n• Guadagnalo da: Ritual Sites e Void Assaults.|n• Spendilo da: Maren Silverwing per i cache di EQUIPAGGIAMENTO Void-Touched (Champion 75 / Hero 500), o Triam Dawnsetter solo per cosmetici. Non trasferibile tra personaggi.|n|n|cffe8c36aCrests (potenziamenti gear)|r|n{CRESTS}|n• Guadagnali da: contenuto all'aperto, delve, dungeon e raid (contenuto più alto = tier più alto).|n• Spendili da: Cuzoth (potenzia gear) e Vaskarn (scambia i crest su o giù di un tier) nel Bazaar. Vedi la tab Crest per la scala completa.|n|n|cffe8c36aValute PvP|r|n• Honor → equipaggiamento Aspirant (Captain Dawnrunner).|n• Conquest → equipaggiamento Champion (Irissa Bloodstar).|n• Bloody Tokens (War Mode) → equipaggiamento Veteran (Knight-Lord Bloodvalor).|n• Marks of Honor → cosmetici Gladiator (Soryn). I vendor PvP stanno sul lato ovest di Silvermoon, vicino a Falconwing Square.|n|n|cffe8c36aRenown Quartermaster (spendi Voidlight Marl)|r|n• Silvermoon Court — Caeris Fairdawn (Saltheril's Haven, Eversong Woods).|n• Amani Tribe — Magovu (Zul'Aman).|n• Hara'ti / Haranir — Naynar (The Den, Harandar).|n• The Singularity — Void Researcher Anomander (Voidstorm).|n|n|cff9aa0a8Nomi dei vendor, costi e posizioni dalla ricerca Wowhead/Method (15 giu) — conferma in gioco. I nomi delle valute rimandano ai tuoi totali in tempo reale.|r",
	DELVELOG_CLEAR = "Cancella registro",
