	MACROS_INTERRUPT_SUBTITLE = "Consiglio Midnight: ferma il cast di un nemico con la pressione di un tasto. Scegli una variante sopra (Focus o Mouseover), leggi la nota, poi copia il testo qui sotto.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Focus",
